package dev.redstoneengineering.block;import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.DifferentialNetwork;import net.minecraft.core.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.*;import net.minecraft.world.level.block.state.BlockState;public class DifferentialDriverBlock extends DirectionalDomainBlock{public DifferentialDriverBlock(Properties p){super(p);}@Override public MapCodec<DifferentialDriverBlock> codec(){return RedstoneEngineering.DIFFERENTIAL_DRIVER_CODEC.value();}private void update(ServerLevel l,BlockPos p,BlockState s){int bit=l.getSignal(inputPos(p,s),inputSide(s))>0?1:0;BlockPos out=outputPos(p,s);if(l.getBlockState(out).getBlock() instanceof DifferentialDataPairBlock)DifferentialNetwork.drive(l,out,bit);}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)update(sl,p,s);}@Override protected void neighborChanged(BlockState s,Level l,BlockPos p,net.minecraft.world.level.block.Block b,BlockPos q,boolean m){if(l instanceof ServerLevel sl)update(sl,p,s);}}